"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[96],{8096:(e,a,s)=>{s.d(a,{D4:()=>t,MD:()=>i,ab:()=>n,sL:()=>o});let i=[{id:1,title:"Getting to know you",zh:"Names, ages, and birthday cards",story:"On the first day, Jack Poon, Lily Wong, and Ken Chan meet in class. Jack is seven. Today is his birthday. Lily and Ken are six. They say Good morning and Nice to meet you. They ask names and ages. Lily opens her lunch box, takes out a cake, and says Happy birthday.",words:[{en:"morning",zh:"the start of the day",emoji:"\uD83C\uDF05",say:"morning"},{en:"afternoon",zh:"after lunch",emoji:"☀️",say:"afternoon"},{en:"Good morning",zh:"hello before lunch",emoji:"\uD83D\uDC4B",say:"Good morning"},{en:"Good afternoon",zh:"hello after lunch",emoji:"\uD83D\uDE0A",say:"Good afternoon"},{en:"Hello",zh:"a friendly hello",emoji:"\uD83D\uDE42",say:"Hello"},{en:"Hi",zh:"a short hello",emoji:"✋",say:"Hi"},{en:"name",zh:"what people call you",emoji:"\uD83C\uDFF7️",say:"name"},{en:"birthday",zh:"the day you were born",emoji:"\uD83C\uDF82",say:"birthday",picture:"/pixabay/birthday.png"}],patterns:[{title:"Ask a name",en:"What is your name? My name is Lily.",zh:"Ask the name, then say My name is ...",examples:["My name is Jack Poon.","My name is Ken Chan."]},{title:"Spell a name",en:"How do you spell your name? L-I-L-Y.",zh:"Say one letter at a time.",examples:["J-A-C-K","K-E-N"]},{title:"Ask an age",en:"How old are you? I am six years old.",zh:"Ask the age, then say I am ... years old.",examples:["I am seven years old.","I am six years old too."]},{title:"Say hello",en:"Nice to meet you.",zh:"Say this when you meet a new friend.",examples:["Hi, Lily. Nice to meet you.","You are welcome."]}],phonics:[{sound:"h",words:["hi","hello","happy"],zh:"starts with h"},{sound:"m",words:["my","meet","morning"],zh:"starts with m"},{sound:"y",words:["you","your","year"],zh:"starts with y"}],writing:["A birthday card has three parts: Dear (who gets the card), Happy birthday! (the wish), From (who writes the card).","You can also write Love or Best wishes.","A name starts with a capital letter."]},{id:2,title:"People at my school",zh:"Friends and teachers",story:"Kate Wood is six. She is from the U.S.A. She lives in China with her mum and dad. Mr Brown is the English teacher. He is from England. He is kind. Wendy Tam is Kate's best friend in Class 1A. Ted Wong is the group leader of Group 1. Sue Clark is the monitress.",words:[{en:"classmate",zh:"a child in your class",emoji:"\uD83E\uDDD2",say:"classmate"},{en:"group leader",zh:"the child who leads a group",emoji:"⭐",say:"group leader"},{en:"monitor",zh:"a boy class helper",emoji:"\uD83D\uDC66",say:"monitor"},{en:"monitress",zh:"a girl class helper",emoji:"\uD83D\uDC67",say:"monitress"},{en:"class teacher",zh:"the teacher of your class",emoji:"\uD83D\uDC69‍\uD83C\uDFEB",say:"class teacher"},{en:"Chinese teacher",zh:"the teacher of Chinese",emoji:"\uD83E\uDDE7",say:"Chinese teacher"},{en:"English teacher",zh:"the teacher of English",emoji:"\uD83D\uDCD8",say:"English teacher"},{en:"Maths teacher",zh:"the teacher of Maths",emoji:"➗",say:"Maths teacher"}],patterns:[{title:"Introduce someone",en:"This is Wendy. She is my classmate.",zh:"This is ... then He is or She is.",examples:["This is Ted. He is our group leader.","This is Mr Brown. He is our English teacher."]},{title:"Say your class",en:"We are in Class 1A.",zh:"Use We are when you talk together.",examples:["We are in Group 1.","We are in Class 1A."]},{title:"my and our",en:"I → my, we → our",zh:"Use my for yourself. Use our for the group.",examples:["She is my best friend.","He is our English teacher."]},{title:"Mr / Mrs / Miss",en:"Mr Hill, Mrs Hill, Miss Ma",zh:"Mr is a man. Mrs is a married woman. Miss is an unmarried woman.",examples:["This is Miss Ma.","This is Mr Hill.","This is Mrs Hill."]}],phonics:[{sound:"b",words:["boy","big","bad"],zh:"starts with b"},{sound:"g",words:["girl","good","get"],zh:"starts with g"},{sound:"t",words:["teacher","tell","ten"],zh:"starts with t"}],writing:["A sentence starts with a capital letter.","The word I is always a capital.","A name starts with a capital letter.","A sentence ends with a full stop.","Example: My name is Judy Lee. I am in Class 1B. I am six years old."]},{id:4,title:"In my school bag",zh:"Things in the bag",story:"Super Boy walks to school on a sunny morning. He has an eraser and a school bag. He helps a cat and a child. A grandma feels unwell. Super Boy has eight pencils and two water bottles. He gives her a bottle of water. She says Thank you. He says No problem.",words:[{en:"school bag",zh:"a bag for school",emoji:"\uD83C\uDF92",say:"school bag",picture:"/pixabay/school-bag.png"},{en:"book",zh:"something you read",emoji:"\uD83D\uDCD7",say:"book",picture:"/pixabay/book.png"},{en:"pencil case",zh:"a box for pens",emoji:"\uD83D\uDD8A️",say:"pencil case"},{en:"lunch box",zh:"a box for lunch",emoji:"\uD83C\uDF71",say:"lunch box",picture:"/pixabay/lunch-box.png"},{en:"water bottle",zh:"a bottle of water",emoji:"\uD83E\uDD64",say:"water bottle",picture:"/pixabay/water-bottle.png"},{en:"pen",zh:"you write with it",emoji:"✒️",say:"pen",picture:"/pixabay/pen.png"},{en:"pencil",zh:"you draw with it",emoji:"✏️",say:"pencil",picture:"/pixabay/pencil.png"},{en:"eraser",zh:"it rubs out marks",emoji:"\uD83E\uDDFD",say:"eraser",picture:"/pixabay/eraser.png"},{en:"ruler",zh:"it draws straight lines",emoji:"\uD83D\uDCCF",say:"ruler",picture:"/pixabay/ruler.png"},{en:"crayon",zh:"a coloured stick",emoji:"\uD83D\uDD8D️",say:"crayon",picture:"/pixabay/crayon.png"}],patterns:[{title:"I have and he has",en:"I have a pen. He has an eraser. She has three pencils.",zh:"I, you, and we use have. He and she use has. Add s for more than one.",examples:["I have eight pencils.","I have two water bottles.","He has a school bag."]},{title:"a and an",en:"a book, an eraser",zh:"Use an before a vowel sound: a, e, i, o, u.",examples:["an apple","an ice cream","an orange","an umbrella","a ruler"]},{title:"Numbers 1 to 10",en:"one, two, three, four, five, six, seven, eight, nine, ten",zh:"One thing can be a or one.",examples:["I have one pen.","She has one eraser.","He has three erasers."]}],phonics:[{sound:"p",words:["pencil","pig","point"],zh:"starts with p"},{sound:"k",words:["kite","book","look"],zh:"the k sound"},{sound:"-en",words:["pen","ten","hen"],zh:"ends with -en"}],writing:["Put a comma before a name: You are great, Super Boy.","A shout uses an exclamation mark: Help! Wow! Oh no!","A question uses a question mark: What is your name?"]}],o=["One, two, take out your glue.","Three, four, touch the floor.","Five, six, write some ticks.","Seven, eight, sit up straight.","Nine, ten, put down your pen."],n=[{id:"g1",unit:1,skill:"greetings",prompt:"How old are you?",hint:"Someone asks your age.",speak:"How old are you?",choices:["I am six years old.","My name is Ken.","Good afternoon."],answer:"I am six years old.",explain:"For an age, say I am ... years old."},{id:"g2",unit:1,skill:"greetings",prompt:"What is your name?",hint:"Someone asks your name.",speak:"What is your name?",choices:["My name is Lily.","I am seven years old.","You are welcome."],answer:"My name is Lily.",explain:"For a name, say My name is ..."},{id:"g3",unit:1,skill:"greetings",prompt:"It is 8 o'clock in the morning. What do you say?",hint:"What do you say in the morning?",speak:"It is eight o'clock in the morning.",choices:["Good morning.","Good afternoon.","Happy birthday!"],answer:"Good morning.",explain:"In the morning, say Good morning. After lunch, say Good afternoon."},{id:"g4",unit:1,skill:"greetings",prompt:"It is 2 o'clock in the afternoon. What do you say?",hint:"What do you say in the afternoon?",choices:["Good afternoon.","Good morning.","Nice to meet you."],answer:"Good afternoon.",explain:"In the afternoon, say Good afternoon."},{id:"g5",unit:1,skill:"greetings",prompt:"A new friend says: Nice to meet you.",hint:"What can you say back?",speak:"Nice to meet you.",choices:["Nice to meet you too.","I have a pen.","I am six years old."],answer:"Nice to meet you too.",explain:"When a friend says Nice to meet you, you can say Nice to meet you too."},{id:"g6",unit:1,skill:"greetings",prompt:"How do you spell the name Lily?",hint:"Say one letter at a time.",choices:["L-I-L-Y","L-Y-L-I","L-I-L-I"],answer:"L-I-L-Y",explain:"Lily is L-I-L-Y."},{id:"g7",unit:1,skill:"greetings",prompt:"Jack is seven. Ken is six. Who is older?",hint:"Who has more years?",choices:["Jack","Ken","They are the same."],answer:"Jack",explain:"Seven is more than six, so Jack is older."},{id:"g8",unit:1,skill:"greetings",prompt:"Which card is correct?",hint:"A card needs Dear, a wish, From, and capital names.",choices:["Dear Lily, Happy birthday! From Ken","dear lily happy birthday from ken","From Lily, Dear birthday"],answer:"Dear Lily, Happy birthday! From Ken",explain:"Dear is the person who gets the card. From is the person who writes it. Names start with a capital letter."},{id:"p1",unit:2,skill:"people",prompt:"This is Wendy. ___ is my classmate.",hint:"Wendy is a girl.",choices:["She","He","We"],answer:"She",explain:"A girl is She. A boy is He. Together is We."},{id:"p2",unit:2,skill:"people",prompt:"This is Ted. ___ is our group leader.",hint:"Ted is a boy.",choices:["He","She","I"],answer:"He",explain:"A boy is He is ..."},{id:"p3",unit:2,skill:"people",prompt:"Kate and Wendy are together. ___ are in Class 1A.",hint:"Two people together.",choices:["We","He","She"],answer:"We",explain:"Together, say We are ..."},{id:"p4",unit:2,skill:"people",prompt:"Kate talks about her own friend: She is ___ best friend.",hint:"Which word is for her own friend?",choices:["my","our","we"],answer:"my",explain:"Your own friend uses my. The class teacher uses our: He is our English teacher."},{id:"p5",unit:2,skill:"people",prompt:"Sue helps the teacher. Sue is a girl. She is the ___.",hint:"What do you call a girl class helper?",choices:["monitress","monitor","Maths teacher"],answer:"monitress",explain:"A girl class helper is a monitress. A boy class helper is a monitor."},{id:"p6",unit:2,skill:"people",prompt:"The English teacher is a man. We call him ___.",hint:"How do you address a man?",choices:["Mr Brown","Mrs Brown","Miss Brown"],answer:"Mr Brown",explain:"A man is Mr. A married woman is Mrs. An unmarried woman is Miss."},{id:"p7",unit:2,skill:"people",prompt:"Which sentence is correct?",hint:"Look at capitals and the full stop.",choices:["My name is Judy Lee.","my name is judy lee","my Name is Judy lee."],answer:"My name is Judy Lee.",explain:"Start with a capital, capital I, capital names, and a full stop."},{id:"p8",unit:2,skill:"people",prompt:"Miss Ma is not married. Mrs Hill is married. Which title is for a married woman?",hint:"A married woman.",choices:["Mrs","Miss","Mr"],answer:"Mrs",explain:"A married woman is Mrs. An unmarried woman is Miss."},{id:"b1",unit:4,skill:"bag",prompt:"I ___ a pencil.",hint:"You are talking about yourself.",choices:["have","has","am"],answer:"have",explain:"I, you, and we use have. He and she use has."},{id:"b2",unit:4,skill:"bag",prompt:"She ___ an eraser.",hint:"A girl has something.",choices:["has","have","is"],answer:"has",explain:"She has ..."},{id:"b3",unit:4,skill:"bag",prompt:"He ___ two water bottles.",hint:"A boy has something.",choices:["has","have","are"],answer:"has",explain:"He has ... More than one thing adds s: bottles."},{id:"b4",unit:4,skill:"bag",prompt:"Choose a or an: ___ orange",hint:"Orange starts with a vowel sound.",choices:["an","a"],answer:"an",explain:"Words that start with a, e, i, o, or u usually use an: an orange, an eraser, an apple."},{id:"b5",unit:4,skill:"bag",prompt:"Choose a or an: ___ book",hint:"Book does not start with a vowel sound.",choices:["a","an"],answer:"a",explain:"Say a book."},{id:"b6",unit:4,skill:"bag",prompt:"Choose a or an: ___ umbrella",hint:"Umbrella starts with u.",choices:["an","a"],answer:"an",explain:"The book uses an umbrella, an ice cream, an apple, an eraser, and an orange."},{id:"b7",unit:4,skill:"bag",prompt:"What is the word for 8?",hint:"Super Boy has eight pencils.",choices:["eight","six","ten"],answer:"eight",explain:"8 is eight. 6 is six. 10 is ten."},{id:"b8",unit:4,skill:"bag",prompt:"One eraser. Three ___.",hint:"More than one needs a plural.",choices:["erasers","eraser","an eraser"],answer:"erasers",explain:"More than one adds s: three erasers, two bottles, eight pencils."},{id:"b9",unit:4,skill:"bag",prompt:"I have one pen. I can also say: I have ___ pen.",hint:"One thing can use a or one.",choices:["a","an","three"],answer:"a",explain:"One ordinary thing is a pen or one pen. An eraser uses an because it starts with a vowel sound."},{id:"m1",unit:4,skill:"marks",prompt:"What is your name___",hint:"This is a question.",choices:["?",".","!"],answer:"?",explain:"A question ends with a question mark."},{id:"m2",unit:4,skill:"marks",prompt:"Help___",hint:"Super Boy hears someone shout.",choices:["!",".","?"],answer:"!",explain:"A shout uses an exclamation mark, like Help! Wow! Oh no!"},{id:"m3",unit:1,skill:"marks",prompt:"I am six years old___",hint:"This is an ordinary sentence.",choices:[".","?","!"],answer:".",explain:"An ordinary sentence ends with a full stop."},{id:"m4",unit:4,skill:"marks",prompt:"You are great ___ Super Boy.",hint:"You are speaking to someone by name.",choices:[",",".","?"],answer:",",explain:"Put a comma before a name: You are great, Super Boy."},{id:"h1",unit:1,skill:"phonics",prompt:"Which word starts with h?",hint:"The h sound, like hi.",speak:"h. hi. hello. happy.",choices:["happy","meet","you"],answer:"happy",explain:"h: hi, hello, happy."},{id:"h2",unit:1,skill:"phonics",prompt:"Which word starts with m?",hint:"The m sound, like my.",speak:"m. my. meet. morning.",choices:["morning","year","hello"],answer:"morning",explain:"m: my, meet, morning."},{id:"h3",unit:1,skill:"phonics",prompt:"Which word starts with y?",hint:"The y sound, like you.",choices:["your","happy","meet"],answer:"your",explain:"y: you, your, year."},{id:"h4",unit:2,skill:"phonics",prompt:"Which word starts with b?",hint:"The b sound.",speak:"b. boy. big. bad.",choices:["boy","girl","teacher"],answer:"boy",explain:"b: boy, big, bad."},{id:"h5",unit:2,skill:"phonics",prompt:"Which word starts with t?",hint:"The t sound.",choices:["ten","good","big"],answer:"ten",explain:"t: teacher, tell, ten."},{id:"h6",unit:4,skill:"phonics",prompt:"Which word has the -en sound?",hint:"The ending en, like pen.",speak:"pen. ten. hen.",choices:["pen","pig","book"],answer:"pen",explain:"-en: pen, ten, hen."},{id:"h7",unit:4,skill:"phonics",prompt:"Which word starts with p?",hint:"The p sound.",choices:["pencil","kite","look"],answer:"pencil",explain:"p: pencil, pig, point."},{id:"h8",unit:2,skill:"phonics",prompt:"Which word starts with g?",hint:"The g sound.",choices:["girl","boy","ten"],answer:"girl",explain:"g: girl, good, get."}],t=[{id:"u1w",text:"Read and spell morning and afternoon. Say Good morning and Good afternoon."},{id:"u1g",text:"Say hello: Hi, Hello, Nice to meet you."},{id:"u1n",text:"Ask and answer What is your name? / My name is ..."},{id:"u1a",text:"Ask and answer How old are you? / I am six years old."},{id:"u1c",text:"Write a birthday card: Dear, Happy birthday!, From."},{id:"u2w",text:"Read classmate, group leader, monitor, monitress, and the subject teachers."},{id:"u2h",text:"Use This is ... He is / She is / We are."},{id:"u2o",text:"Use my and our."},{id:"u2m",text:"Use Mr, Mrs, and Miss."},{id:"u2p",text:"Capital at the start, capital I, capital names, and a full stop."},{id:"u4w",text:"Name the ten things in a school bag, and the numbers one to ten."},{id:"u4h",text:"Use I have / He has / She has. Add s for more than one."},{id:"u4a",text:"Use a and an."},{id:"u4m",text:"Use a comma before a name, a question mark, and an exclamation mark."}]}}]);